<?= $this->extend('layouts/volunteer') ?>
<?= $this->section('content') ?>
<div><h1 class="text-3xl font-bold tracking-[-.025em]">My Tasks</h1><p class="text-slate-500">Active assignments and today’s work.</p></div>
<div class="grid gap-6 md:grid-cols-4"><?php foreach ([['Active Tasks', count($tasks)], ['Completed', count(array_filter($tasks, fn($t)=>$t['status']==='Completed'))], ['High Priority', count(array_filter($tasks, fn($t)=>$t['priority']==='High'))], ['Due Today', count(array_filter($tasks, fn($t)=>$t['task_date']===date('Y-m-d')))]] as $s): ?><div class="card"><div class="text-2xl font-bold"><?= esc($s[1]) ?></div><div class="text-sm font-medium text-slate-500"><?= esc($s[0]) ?></div></div><?php endforeach; ?></div>
<form method="get" class="card grid gap-3 md:grid-cols-[1fr_180px_180px_auto]"><input name="q" value="<?= esc($search) ?>" class="field" placeholder="Search task title, details, or cat name"><select name="status" class="field"><option value="">All statuses</option><?php foreach(['Pending','In Progress','Overdue','Completed'] as $value): ?><option value="<?= $value ?>" <?= $selectedStatus===$value?'selected':'' ?>><?= $value ?></option><?php endforeach; ?></select><select name="category" class="field"><option value="">All categories</option><?php foreach(['Feeding','Cleaning','Medical','Transport','Socialization','Walking','Adoption'] as $value): ?><option value="<?= $value ?>" <?= $selectedCategory===$value?'selected':'' ?>><?= $value ?></option><?php endforeach; ?></select><button class="btn btn-primary justify-center"><i data-lucide="sliders-horizontal" class="h-4 w-4"></i>Filter</button></form>
<div class="space-y-3"><?php foreach ($tasks as $task): ?><a href="<?= site_url('volunteer/task/' . $task['id']) ?>" class="card block hover:border-rescue-200"><div class="mb-2 flex gap-2"><?= statusBadge($task['priority']) ?><?= statusBadge($task['status']) ?><span class="rounded-full bg-slate-100 px-2.5 py-0.5 text-xs font-semibold text-slate-600"><?= esc($task['category']) ?></span></div><h2 class="font-bold"><?= esc($task['title']) ?></h2><p class="text-sm text-slate-500"><?= esc($task['task_date']) ?> <?= esc(substr((string)$task['task_time'],0,5)) ?> · <?= esc($task['location']) ?></p><?php if ($task['animal_name']): ?><p class="mt-2 text-sm font-semibold text-rescue-600">Cat: <?= esc($task['animal_name']) ?></p><?php endif; ?></a><?php endforeach; ?></div>
<?= $this->endSection() ?>
